"""Add GitHub OAuth team sign-in to the existing MLFlowPro dashboard."""

import ast
from datetime import datetime
from pathlib import Path
import re

FILES = {'backend/experiments/github_auth.py': '"""GitHub OAuth entry points and the class project\'s team access policy."""\n\nfrom django.conf import settings\nfrom django.contrib.auth import logout\nfrom django.shortcuts import redirect, render\nfrom django.views.decorators.csrf import csrf_protect\nfrom django.views.decorators.http import require_GET, require_POST\n\nfrom allauth.core.exceptions import ImmediateHttpResponse\nfrom allauth.socialaccount.adapter import DefaultSocialAccountAdapter\nfrom allauth.socialaccount.providers.github.views import oauth2_callback, oauth2_login\n\n\ndef github_is_configured():\n    github = settings.SOCIALACCOUNT_PROVIDERS.get("github", {})\n    application = github.get("APP", {})\n    return bool(application.get("client_id") and application.get("secret"))\n\n\ndef github_login_context(request):\n    return {"github_login_configured": github_is_configured()}\n\n\ndef authentication_message(request, message, status):\n    return render(request, "experiments/github_auth_error.html", {\n        "authentication_message": message,\n    }, status=status)\n\n\nclass TeamSocialAccountAdapter(DefaultSocialAccountAdapter):\n    def allowed(self, sociallogin):\n        github_name = str(sociallogin.account.extra_data.get("login", "")).casefold()\n        allowed = {name.casefold() for name in settings.MLFLOWPRO_GITHUB_ALLOWED_USERS}\n        return sociallogin.account.provider == "github" and github_name in allowed\n\n    def pre_social_login(self, request, sociallogin):\n        # Runs for returning accounts too, before a Django login session is issued.\n        if not self.allowed(sociallogin):\n            raise ImmediateHttpResponse(authentication_message(\n                request, "This GitHub account is not on the project team\'s access list.", 403,\n            ))\n        return super().pre_social_login(request, sociallogin)\n\n    def is_open_for_signup(self, request, sociallogin):\n        return self.allowed(sociallogin)\n\n    def populate_user(self, request, sociallogin, data):\n        # Identity uses GitHub\'s account ID and login; no private email permission is needed.\n        fields = dict(data)\n        fields["email"] = ""\n        sociallogin.email_addresses = []\n        return super().populate_user(request, sociallogin, fields)\n\n\n@require_POST\n@csrf_protect\ndef github_login(request):\n    if not github_is_configured():\n        return authentication_message(request, "Team sign-in is temporarily unavailable.", 503)\n    return oauth2_login(request)\n\n\n@require_GET\ndef github_callback(request):\n    if not github_is_configured():\n        return authentication_message(request, "Team sign-in is temporarily unavailable.", 503)\n    return oauth2_callback(request)\n\n\n@require_POST\n@csrf_protect\ndef team_logout(request):\n    logout(request)\n    return redirect("/")\n', 'backend/experiments/test_github_auth.py': '"""Exercise the real OAuth redirects and callback using mocked GitHub HTTP."""\n\nimport json\nfrom urllib.parse import parse_qs, urlparse\nfrom unittest.mock import patch\n\nimport requests\nfrom allauth.socialaccount.models import SocialAccount, SocialToken\nfrom django.contrib.auth import get_user_model\nfrom django.core.cache import cache\nfrom django.test import Client, TestCase, override_settings\n\nfrom .models import Experiment\n\n\nTEST_PROVIDER = {\n    "github": {\n        "APP": {"client_id": "github-test-client-id", "secret": "github-test-client-secret", "key": ""},\n        "SCOPE": [],\n        "OAUTH_PKCE_ENABLED": True,\n    },\n}\n\n\n@override_settings(\n    SOCIALACCOUNT_PROVIDERS=TEST_PROVIDER,\n    MLFLOWPRO_GITHUB_ALLOWED_USERS=("Elitelige7", "elsow1", "KHD-wq"),\n    ACCOUNT_RATE_LIMITS={},\n)\nclass GitHubAuthenticationTests(TestCase):\n    def setUp(self):\n        cache.clear()\n        self.client = Client(enforce_csrf_checks=True)\n        self.http_calls = []\n\n    def csrf(self):\n        response = self.client.get("/")\n        self.assertEqual(response.status_code, 200)\n        return self.client.cookies["csrftoken"].value\n\n    def start_login(self, **request_options):\n        token = self.csrf()\n        response = self.client.post("/accounts/github/login/", HTTP_X_CSRFTOKEN=token, **request_options)\n        self.assertEqual(response.status_code, 302)\n        return response, parse_qs(urlparse(response["Location"]).query)\n\n    def github_response(self, method, url, **kwargs):\n        self.http_calls.append((method.upper(), url, kwargs))\n        if method.upper() == "POST" and url == "https://github.com/login/oauth/access_token":\n            value = {"access_token": "test-provider-token", "token_type": "bearer", "expires_in": 28800,\n                     "refresh_token": "test-refresh-token"}\n        elif method.upper() == "GET" and url == "https://api.github.com/user":\n            value = {"id": self.github_id, "login": self.github_name, "name": "Test Team Member",\n                     "email": "unused-public-email@example.com"}\n        else:\n            raise AssertionError("Unexpected external request in OAuth test: " + url)\n        result = requests.Response()\n        result.status_code = 200\n        result.headers["content-type"] = "application/json"\n        result._content = json.dumps(value).encode("utf-8")\n        return result\n\n    def finish_login(self, name="Elitelige7", identity=314159):\n        self.github_name, self.github_id = name, identity\n        _, query = self.start_login()\n        with patch("requests.sessions.Session.request", side_effect=self.github_response):\n            response = self.client.get("/accounts/github/login/callback/", {\n                "code": "temporary-test-authorization-code", "state": query["state"][0],\n            })\n        return response\n\n    def test_dashboard_has_sign_in_and_does_not_expose_credentials(self):\n        response = self.client.get("/")\n        self.assertContains(response, "Sign in with GitHub")\n        self.assertContains(response, \'name="csrfmiddlewaretoken"\')\n        self.assertNotContains(response, "github-test-client-secret")\n        self.assertNotContains(response, "github-test-client-id")\n        self.assertContains(response, "Shared Experiment Notes")\n\n    def test_missing_credentials_disable_button_and_fail_gracefully(self):\n        with override_settings(SOCIALACCOUNT_PROVIDERS={"github": {"APP": {"client_id": "", "secret": ""}}}):\n            response = self.client.get("/")\n            self.assertContains(response, \'id="github-sign-in-btn" disabled\')\n            token = self.csrf()\n            response = self.client.post("/accounts/github/login/", HTTP_X_CSRFTOKEN=token)\n            self.assertEqual(response.status_code, 503)\n            self.assertContains(response, "temporarily unavailable", status_code=503)\n            self.assertEqual(self.client.get("/accounts/github/login/callback/").status_code, 503)\n\n    def test_login_requires_post_and_csrf(self):\n        self.assertEqual(self.client.get("/accounts/github/login/").status_code, 405)\n        self.assertEqual(self.client.post("/accounts/github/login/").status_code, 403)\n        self.assertNotIn("_auth_user_id", self.client.session)\n\n    def test_authorization_redirect_uses_state_pkce_and_exact_local_callback(self):\n        response, query = self.start_login(HTTP_HOST="127.0.0.1:8000")\n        self.assertEqual(urlparse(response["Location"]).netloc, "github.com")\n        self.assertEqual(query["client_id"], ["github-test-client-id"])\n        self.assertEqual(query["redirect_uri"], ["http://127.0.0.1:8000/accounts/github/login/callback/"])\n        self.assertTrue(query["state"][0])\n        self.assertEqual(query["code_challenge_method"], ["S256"])\n        self.assertEqual(len(query["code_challenge"][0]), 43)\n        self.assertNotIn("scope", query)\n        self.assertNotIn("github-test-client-secret", response["Location"])\n\n    def test_https_proxy_produces_https_callback(self):\n        with override_settings(ALLOWED_HOSTS=["testserver", "hardyboys-ml-project.onrender.com"]):\n            _, query = self.start_login(HTTP_HOST="hardyboys-ml-project.onrender.com",\n                                        HTTP_ORIGIN="https://hardyboys-ml-project.onrender.com",\n                                        HTTP_X_FORWARDED_PROTO="https", secure=True)\n        self.assertEqual(query["redirect_uri"], [\n            "https://hardyboys-ml-project.onrender.com/accounts/github/login/callback/",\n        ])\n\n    def test_allowed_github_callback_creates_session_without_saving_tokens(self):\n        response = self.finish_login("elitelige7")\n        self.assertEqual(response.status_code, 302)\n        self.assertEqual(response["Location"], "/")\n        user = get_user_model().objects.get(pk=self.client.session["_auth_user_id"])\n        self.assertEqual(user.username, "elitelige7")\n        self.assertFalse(user.has_usable_password())\n        self.assertEqual(user.email, "")\n        account = SocialAccount.objects.get(user=user)\n        self.assertEqual(account.provider, "github")\n        self.assertEqual(account.uid, "314159")\n        self.assertEqual(SocialToken.objects.count(), 0)\n        token_call = self.http_calls[0][2]["data"]\n        self.assertEqual(token_call["client_secret"], "github-test-client-secret")\n        self.assertTrue(token_call["code_verifier"])\n        self.assertEqual(len(self.http_calls), 2)\n        page = self.client.get("/")\n        self.assertContains(page, "Signed in as")\n        self.assertContains(page, "elitelige7")\n        self.assertNotContains(page, "test-provider-token")\n\n    def test_returning_github_account_reuses_user(self):\n        self.assertEqual(self.finish_login().status_code, 302)\n        original_id = self.client.session["_auth_user_id"]\n        self.client.logout()\n        self.assertEqual(self.finish_login().status_code, 302)\n        self.assertEqual(self.client.session["_auth_user_id"], original_id)\n        self.assertEqual(get_user_model().objects.count(), 1)\n        self.assertEqual(SocialAccount.objects.count(), 1)\n\n    def test_unlisted_github_account_is_denied_before_user_creation(self):\n        response = self.finish_login("not-on-the-team", identity=271828)\n        self.assertEqual(response.status_code, 403)\n        self.assertContains(response, "access list.", status_code=403)\n        self.assertNotIn("_auth_user_id", self.client.session)\n        self.assertEqual(get_user_model().objects.count(), 0)\n        self.assertEqual(SocialAccount.objects.count(), 0)\n\n    def test_returning_user_removed_from_allowlist_cannot_sign_in_again(self):\n        self.assertEqual(self.finish_login().status_code, 302)\n        self.client.logout()\n        with override_settings(MLFLOWPRO_GITHUB_ALLOWED_USERS=("elsow1",)):\n            response = self.finish_login()\n        self.assertEqual(response.status_code, 403)\n        self.assertNotIn("_auth_user_id", self.client.session)\n\n    def test_invalid_state_cannot_exchange_code_or_create_session(self):\n        self.start_login()\n        with patch("requests.sessions.Session.request") as external:\n            response = self.client.get("/accounts/github/login/callback/", {\n                "code": "untrusted-code", "state": "does-not-match-session",\n            })\n        external.assert_not_called()\n        self.assertLess(response.status_code, 500)\n        self.assertNotIn("_auth_user_id", self.client.session)\n\n    def test_logged_in_predictions_work_with_csrf_and_reject_missing_token(self):\n        self.assertEqual(self.finish_login().status_code, 302)\n        token = self.csrf()\n        payload = {"review": "This was an excellent movie with great acting."}\n        denied = self.client.post("/api/predict/", payload, content_type="application/json")\n        self.assertEqual(denied.status_code, 403)\n        response = self.client.post("/api/predict/", payload, content_type="application/json", HTTP_X_CSRFTOKEN=token)\n        self.assertEqual(response.status_code, 200)\n        self.assertEqual(response.json()["prediction"], "Positive")\n        self.assertContains(self.client.get("/"), "X-CSRFToken")\n\n    def test_authenticated_team_can_create_experiment_but_anonymous_cannot(self):\n        payload = {"name": "OAuth-created experiment", "description": "OAuth test fixture", "dataset": "Test"}\n        anonymous = self.client.post("/api/experiments/", payload, content_type="application/json")\n        self.assertIn(anonymous.status_code, [401, 403])\n        self.assertEqual(self.finish_login().status_code, 302)\n        response = self.client.post("/api/experiments/", payload, content_type="application/json",\n                                    HTTP_X_CSRFTOKEN=self.csrf())\n        self.assertEqual(response.status_code, 201)\n        self.assertTrue(Experiment.objects.filter(name="OAuth-created experiment").exists())\n\n    def test_logout_requires_csrf_and_ends_session(self):\n        self.assertEqual(self.finish_login().status_code, 302)\n        self.assertEqual(self.client.get("/team/logout/").status_code, 405)\n        self.assertEqual(self.client.post("/team/logout/").status_code, 403)\n        response = self.client.post("/team/logout/", HTTP_X_CSRFTOKEN=self.csrf())\n        self.assertEqual(response.status_code, 302)\n        self.assertEqual(response["Location"], "/")\n        self.assertNotIn("_auth_user_id", self.client.session)\n\n    def test_native_password_signup_is_unavailable(self):\n        self.assertEqual(self.client.get("/accounts/signup/").status_code, 404)\n        self.assertEqual(self.client.get("/accounts/password/reset/").status_code, 404)\n', 'backend/templates/experiments/github_auth_error.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Team sign-in | MLFlowPro</title>\n  <style>\n    body { font-family: Arial, sans-serif; max-width: 800px; margin: 30px auto; padding: 0 20px; color: #333; }\n    main { border: 1px solid #e0e0e0; border-radius: 8px; padding: 24px; }\n    a { color: #0056b3; }\n  </style>\n</head>\n<body>\n  <main>\n    <h1>Team sign-in</h1>\n    <p>{{ authentication_message }}</p>\n    <p><a href="/">Return to dashboard</a></p>\n  </main>\n</body>\n</html>\n', 'docs/github-login.md': '# GitHub OAuth2 team sign-in\n\nThe dashboard can sign team members in through GitHub. GitHub verifies their\nidentity; Django creates a session only when their GitHub username is allowed.\nThe default list is `Elitelige7,elsow1,KHD-wq`. Add your professor\'s exact GitHub\nusername to `GITHUB_ALLOWED_USERS` if they need team access.\n\nPublic predictions, the version list, and performance results remain accessible\nwithout signing in. Existing authenticated experiment APIs also accept the\nGitHub session. AI suggestions and shared notes continue using their team access\ncode. GitHub sign-in does not require OpenAI credits.\n\n## 1. Install the feature from PowerShell\n\nSave `add_github_login.py` beside `publish_model.py` in your project root. Stop\nyour local Django server with Ctrl+C, then run:\n\n```powershell\ncd C:\\Users\\elige\\hardyboys-ml-project\n.\\.venv\\Scripts\\Activate.ps1\npython add_github_login.py\npython -m pip install -r backend/requirements.txt\npython backend/manage.py migrate\npython -m pytest -q\n```\n\nThe helper preserves your dashboard\'s existing styles and cards. It adds a\nsign-in strip and a CSRF token on prediction requests. Backups of edited files\nare stored under `local_jobs/backups/`, which your project already ignores.\n\n## 2. Register one GitHub OAuth application\n\nOpen https://github.com/settings/applications/new and enter:\n\n| Field | Value |\n| --- | --- |\n| Application name | HardyBoys MLFlowPro |\n| Homepage URL | `https://hardyboys-ml-project.onrender.com/` |\n| Authorization callback URL | `https://hardyboys-ml-project.onrender.com/accounts/github/login/callback/` |\n| Additional callback URL | `http://127.0.0.1:8000/accounts/github/login/callback/` |\n\nUse **Add callback URL** for the second address. Keep device flow disabled; this\nfeature uses the browser flow. Expiring access tokens can remain enabled: the\nserver uses a token immediately to verify identity and does not save it for\nlater API use. Click **Register application**, then **Generate a new client\nsecret**. GitHub supplies the Client ID and Client Secret.\n\n## 3. Set your local credentials\n\nOpen `backend/.env` in VS Code. Add these lines, replacing the first two values:\n\n```dotenv\nGITHUB_CLIENT_ID=your_actual_github_client_id\nGITHUB_CLIENT_SECRET=your_actual_github_client_secret\nGITHUB_ALLOWED_USERS=Elitelige7,elsow1,KHD-wq\n```\n\nLeave your existing Django, database, and OpenAI settings in the file. Keep\n`backend/.env` out of Git. Restart the local server:\n\n```powershell\npython backend/manage.py runserver\n```\n\nVisit http://127.0.0.1:8000/ (use this hostname rather than `localhost` so the\ncallback matches). Click **Sign in with GitHub** and authorize the application.\nYou should return to the dashboard with **Signed in as** and your username.\nRun a prediction, then sign out. The authorization request asks for no additional\nGitHub scopes; it does not request repository access or private email access.\n\n## 4. Deploy to Render\n\nReview and commit the feature files on your existing feature branch:\n\n```powershell\ngit add add_github_login.py backend/MLFlowPro/settings.py backend/MLFlowPro/urls.py\ngit add backend/experiments/github_auth.py backend/experiments/test_github_auth.py\ngit add backend/templates/experiments/github_auth_error.html backend/index.html\ngit add backend/requirements.txt docs/github-login.md\ngit diff --cached --stat\ngit commit -m "Add GitHub OAuth2 team sign-in"\ngit push\n```\n\nIn https://dashboard.render.com/, open `hardyboys-ml-project` and **Environment**.\nAdd the same three variables from step 3, using your real values. Keep the\nexisting environment variables and the start command `python run_asgi.py`.\nDeploy the branch containing your commit. Your existing build script must run\n`python backend/manage.py migrate --noinput`; allauth supplies the new database\nmigrations, so no new experiments migration is needed for this feature.\n\nTest sign-in, prediction, and sign-out at the public HTTPS address. Check the\nGitHub Actions run after pushing. A successful mocked test run cannot verify\nyour real GitHub credentials or Render environment settings.\n\n## How it works\n\n1. A CSRF-protected form starts the authorization request. Allauth stores random\n   state and a PKCE verifier in the Django session.\n2. GitHub redirects to the matching callback URL with a temporary code.\n3. Django validates the state, exchanges the code server-side, and fetches the\n   GitHub account ID and username.\n4. The adapter checks the username against `GITHUB_ALLOWED_USERS`, including on\n   returning sign-ins. Unlisted accounts receive HTTP 403 without a new account.\n5. Approved accounts receive a Django session. Their account has no local\n   password; the client secret and provider tokens are never sent to the page.\n\nGitHub account IDs identify saved social accounts. The access list uses\ncase-insensitive GitHub usernames; update it if a teammate renames their account.\nRemoving someone prevents their next sign-in; it does not revoke an already\nactive Django session. Do not describe this class demo as complete enterprise\nidentity management.\n\n## Verification and troubleshooting\n\n`test_github_auth.py` tests the actual authorization redirect and callback with\nmocked GitHub HTTP responses, state/PKCE, team restrictions, returning users,\nCSRF, authenticated API access, prediction after login, and logout. It also\nchecks that credentials and tokens are absent from the page and no social token\nis stored in the database.\n\n- **Disabled sign-in:** set both GitHub credential variables and restart/deploy.\n- **Redirect URI mismatch:** copy the callback exactly, including the scheme,\n  hostname, and trailing slash; register both local and live callbacks.\n- **403 after GitHub authorization:** confirm the GitHub username is allowed.\n- **CSRF failure after sign-in:** refresh the dashboard before submitting; old\n  tabs can have the token issued before the login session changed.\n- **Missing table error:** run migrations against the database used by the app.\n- **MultipleObjectsReturned for SocialApp:** credentials belong in the settings\n  environment configuration; do not create a second GitHub SocialApp in admin.\n\nReferences:\n\n- https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/creating-an-oauth-app\n- https://docs.github.com/en/apps/oauth-apps/building-oauth-apps/authorizing-oauth-apps\n- https://docs.allauth.org/en/latest/installation/quickstart.html\n- https://docs.allauth.org/en/latest/socialaccount/provider_configuration.html\n'}

SETTINGS = '# MLFlowPro: GitHub OAuth team sign-in\nfor _oauth_app in (\n    "allauth", "allauth.account", "allauth.socialaccount",\n    "allauth.socialaccount.providers.github",\n):\n    if _oauth_app not in INSTALLED_APPS:\n        INSTALLED_APPS.append(_oauth_app)\n_oauth_middleware = "allauth.account.middleware.AccountMiddleware"\nif _oauth_middleware not in MIDDLEWARE:\n    _oauth_auth_index = MIDDLEWARE.index("django.contrib.auth.middleware.AuthenticationMiddleware")\n    MIDDLEWARE.insert(_oauth_auth_index + 1, _oauth_middleware)\nAUTHENTICATION_BACKENDS = list(globals().get("AUTHENTICATION_BACKENDS", [\n    "django.contrib.auth.backends.ModelBackend",\n]))\nif "allauth.account.auth_backends.AuthenticationBackend" not in AUTHENTICATION_BACKENDS:\n    AUTHENTICATION_BACKENDS.append("allauth.account.auth_backends.AuthenticationBackend")\nfor _oauth_template in TEMPLATES:\n    if _oauth_template.get("BACKEND") == "django.template.backends.django.DjangoTemplates":\n        _oauth_processors = _oauth_template.setdefault("OPTIONS", {}).setdefault("context_processors", [])\n        for _oauth_processor in (\n            "django.template.context_processors.request",\n            "experiments.github_auth.github_login_context",\n        ):\n            if _oauth_processor not in _oauth_processors:\n                _oauth_processors.append(_oauth_processor)\n        _oauth_template_dirs = _oauth_template.setdefault("DIRS", [])\n        if BASE_DIR / "templates" not in _oauth_template_dirs:\n            _oauth_template_dirs.append(BASE_DIR / "templates")\n\nSOCIALACCOUNT_ONLY = True\nSOCIALACCOUNT_ADAPTER = "experiments.github_auth.TeamSocialAccountAdapter"\nSOCIALACCOUNT_LOGIN_ON_GET = False\nSOCIALACCOUNT_AUTO_SIGNUP = True\nSOCIALACCOUNT_STORE_TOKENS = False\nSOCIALACCOUNT_QUERY_EMAIL = False\nSOCIALACCOUNT_EMAIL_AUTHENTICATION = False\nACCOUNT_EMAIL_VERIFICATION = "none"\nACCOUNT_LOGIN_METHODS = {"username"}\nACCOUNT_SIGNUP_FIELDS = ["username*"]\nLOGIN_REDIRECT_URL = "/"\nLOGOUT_REDIRECT_URL = "/"\n\nMLFLOWPRO_GITHUB_ALLOWED_USERS = tuple(\n    _github_name.strip() for _github_name in os.getenv(\n        "GITHUB_ALLOWED_USERS", "Elitelige7,elsow1,KHD-wq",\n    ).split(",") if _github_name.strip()\n)\nSOCIALACCOUNT_PROVIDERS = {\n    "github": {\n        "APP": {\n            "client_id": os.getenv("GITHUB_CLIENT_ID", "").strip(),\n            "secret": os.getenv("GITHUB_CLIENT_SECRET", "").strip(),\n            "key": "",\n        },\n        "SCOPE": [],\n        "OAUTH_PKCE_ENABLED": True,\n    },\n}\n'

LOGIN = '  <!-- MLFlowPro: GitHub team sign-in -->\n  <div id="team-sign-in" style="margin-bottom:20px; padding:12px 0;">\n    {% if request.user.is_authenticated %}\n      <p>Signed in as <strong>{{ request.user.username }}</strong>.</p>\n      <form action="/team/logout/" method="post">\n        {% csrf_token %}\n        <button type="submit">Sign out</button>\n      </form>\n    {% else %}\n      <form action="/accounts/github/login/" method="post">\n        {% csrf_token %}\n        <button type="submit" id="github-sign-in-btn"{% if not github_login_configured %} disabled{% endif %}>Sign in with GitHub</button>\n      </form>\n      {% if not github_login_configured %}<p style="font-size:13px; color:#666;">Team sign-in is temporarily unavailable.</p>{% endif %}\n    {% endif %}\n  </div>\n\n'

URL_IMPORT = '# MLFlowPro: GitHub OAuth routes\nfrom experiments.github_auth import github_login, github_callback, team_logout\n\n'

URL_ROUTES = '\n    path("accounts/github/login/", github_login),\n    path("accounts/github/login/callback/", github_callback),\n    path("team/logout/", team_logout, name="team-logout"),\n    path("accounts/", include("allauth.urls")),\n'

HEADERS = 'headers: {\n            \'Content-Type\': \'application/json\',\n            \'X-CSRFToken\': document.querySelector(\'#review-form input[name="csrfmiddlewaretoken"]\').value,\n          }'



def main():
    root = Path(__file__).resolve().parent
    required = ["backend/manage.py", "backend/index.html", "backend/MLFlowPro/settings.py",
                "backend/MLFlowPro/urls.py", "backend/requirements.txt"]
    missing = [name for name in required if not (root / name).is_file()]
    if missing:
        raise SystemExit("Save this helper in your project root first. Missing: " + ", ".join(missing))
    contents = dict(FILES)

    settings = (root / "backend/MLFlowPro/settings.py").read_text(encoding="utf-8-sig")
    if "# MLFlowPro: GitHub OAuth team sign-in" not in settings:
        if re.search(r"^SOCIALACCOUNT_PROVIDERS\s*=", settings, re.MULTILINE):
            raise SystemExit("An existing OAuth configuration needs review. No files changed.")
        settings = settings.rstrip() + "\n\n" + SETTINGS
    contents["backend/MLFlowPro/settings.py"] = settings

    urls = (root / "backend/MLFlowPro/urls.py").read_text(encoding="utf-8-sig")
    if "# MLFlowPro: GitHub OAuth routes" not in urls:
        declaration = re.search(r"^urlpatterns\s*=\s*\[", urls, re.MULTILINE)
        if declaration is None:
            raise SystemExit("The project's URL list was not found. No files changed.")
        urls = urls[:declaration.start()] + URL_IMPORT + urls[declaration.start():]
        urls = re.sub(r"(^urlpatterns\s*=\s*\[)", lambda match: match.group(1) + URL_ROUTES,
                      urls, count=1, flags=re.MULTILINE)
    contents["backend/MLFlowPro/urls.py"] = urls

    page = (root / "backend/index.html").read_text(encoding="utf-8-sig")
    if "<!-- MLFlowPro: GitHub team sign-in -->" not in page:
        body = re.search(r"<body\b[^>]*>", page, re.IGNORECASE)
        if body is None:
            raise SystemExit("The dashboard's body was not found. No files changed.")
        page = page[:body.end()] + "\n\n" + LOGIN + page[body.end():]
    form = re.search(r'<form\b[^>]*\bid=[\'\"]review-form[\'\"][^>]*>', page, re.IGNORECASE)
    if form is None:
        raise SystemExit("The review form was not found. No files changed.")
    end_form = page.find("</form>", form.end())
    if end_form == -1:
        raise SystemExit("The review form's closing tag was not found. No files changed.")
    if "{% csrf_token %}" not in page[form.end():end_form]:
        page = page[:form.end()] + "\n      {% csrf_token %}" + page[form.end():]
    prediction = re.search(r'fetch\([^\n]*?/api/predict/[^\n]*?\{', page)
    if prediction is None:
        raise SystemExit("The dashboard's prediction request was not found. No files changed.")
    prediction_end = page.find("body:", prediction.end())
    if prediction_end == -1:
        raise SystemExit("The prediction request format needs review. No files changed.")
    request_headers = page[prediction.end():prediction_end]
    if "X-CSRFToken" not in request_headers:
        request_headers, count = re.subn(
            r"headers:\s*\{[^}]*?\}", HEADERS, request_headers, count=1,
        )
        if count != 1:
            raise SystemExit("The prediction headers need review. No files changed.")
        page = page[:prediction.end()] + request_headers + page[prediction_end:]
    contents["backend/index.html"] = page

    requirements = (root / "backend/requirements.txt").read_text(encoding="utf-8-sig")
    dependency = "django-allauth[socialaccount]==65.20.0"
    pattern = r"^django-allauth(?:\[[^\]]+\])?[^\n]*$"
    if re.search(pattern, requirements, re.IGNORECASE | re.MULTILINE):
        requirements = re.sub(pattern, dependency, requirements, flags=re.IGNORECASE | re.MULTILINE)
    else:
        requirements = requirements.rstrip() + "\n" + dependency + "\n"
    contents["backend/requirements.txt"] = requirements

    for relative, content in contents.items():
        if relative.endswith(".py"):
            ast.parse(content, filename=relative)
    backup = root / "local_jobs" / "backups" / ("github-login-" + datetime.now().strftime("%Y%m%d-%H%M%S-%f"))
    for relative, content in contents.items():
        target = root / relative
        if target.is_file() and target.read_text(encoding="utf-8") != content:
            saved = backup / relative
            saved.parent.mkdir(parents=True, exist_ok=True)
            saved.write_bytes(target.read_bytes())
    for relative, content in contents.items():
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        print("Ready:", relative)
    if backup.exists():
        print("Previous files backed up at:", backup)
    print("Next: install backend/requirements.txt, migrate, and run the tests.")
    print("Then set GITHUB_CLIENT_ID, GITHUB_CLIENT_SECRET, and GITHUB_ALLOWED_USERS.")
    print("Setup guide: docs/github-login.md")


if __name__ == "__main__":
    main()
